import React, { useState } from 'react';
import { LayoutDashboard, Truck, History, Users, Radio, Zap, Target, Database } from 'lucide-react';

const Dashboard = () => {
  const [activeTab, setActiveTab] = useState('OVERVIEW');

  const navItems = [
    { id: 'OVERVIEW', icon: <LayoutDashboard />, label: 'SYSTEM_MAP' },
    { id: 'FLEET', icon: <Truck />, label: 'UNIT_STATUS' },
    { id: 'HISTORY', icon: <History />, label: 'DATA_LOGS' },
    { id: 'USERS', icon: <Users />, label: 'NODES' },
  ];

  return (
    <div className="w-full max-w-[1200px] min-h-[800px] flex flex-col items-center justify-center p-6 animate-slot relative">

      {/* --- THE OUTER CHASSIS (Heavy Red Frame) --- */}
      <div className="w-full bg-[#AB1717] border-[10px] border-[#47510B] rounded-[60px] p-8 red-stack-shadow relative flex flex-col gap-8 shadow-[20px_20px_0_0_#47510B]">

        {/* TOP STATUS LIGHTS & BRANDING */}
        <div className="flex justify-between items-center px-4">
          <div className="flex gap-2">
            {[1, 2, 3].map(i => (
              <div key={i} className="w-6 h-2 bg-[#CAD23C] rounded-full border-2 border-[#47510B] animate-pulse" style={{ animationDelay: `${i * 0.2}s` }} />
            ))}
          </div>
          <h1 className="text-4xl font-black italic tracking-tighter text-[#FDFAD8] uppercase">
            TRASH<span className="text-[#CAD23C]">2</span>TRACK
          </h1>
          <div className="text-[10px] font-black text-[#FDFAD8] bg-[#47510B] px-4 py-1 rounded-full border-2 border-[#CAD23C]">
            OS_VERSION: 3.0.1
          </div>
        </div>

        {/* --- THE CENTRAL MONITOR (Blue-Grey Octagon) --- */}
        <div className="relative flex-grow bg-[#A1AED1] border-[8px] border-[#47510B] rounded-[40px] panel-inset-shadow overflow-hidden flex flex-col">
          {/* Scanning Grid Overlay */}
          <div className="absolute inset-0 opacity-20 pointer-events-none" 
               style={{ backgroundImage: 'radial-gradient(#47510B 1.5px, transparent 1.5px)', backgroundSize: '30px 30px' }} />

          {/* DYNAMIC CONTENT SCREEN */}
          <div className="relative z-10 p-8 h-full flex flex-col">

            {/* Header of the Screen */}
            <div className="flex justify-between items-start mb-6">
              <div className="bg-[#47510B] text-[#CAD23C] p-3 rounded-lg font-mono text-xs border-2 border-[#FDFAD8]/20">
                CURRENT_LAYER: {activeTab}
              </div>
              <div className="flex flex-col items-end gap-1">
                <span className="text-[#47510B] font-black text-xs uppercase tracking-widest">Signal_Strength</span>
                <div className="flex gap-1">
                  {[1, 2, 3, 4, 5].map(i => <div key={i} className="w-1 h-4 bg-[#AB1717] border border-[#47510B]" />)}
                </div>
              </div>
            </div>

            {/* Content Logic */}
            <div className="flex-grow flex items-center justify-center">
              {activeTab === 'OVERVIEW' && (
                <div className="text-center animate-slot">
                  <div className="w-64 h-64 border-[10px] border-dashed border-[#AB1717]/30 rounded-full flex items-center justify-center animate-spin-slow">
                    <Radio size={80} className="text-[#AB1717] animate-pulse" />
                  </div>
                  <p className="mt-6 font-black text-[#47510B] tracking-[0.5em] uppercase">Broadcasting_Live_Nodes</p>
                </div>
              )}
              {activeTab === 'FLEET' && (
                <div className="grid grid-cols-2 gap-4 w-full animate-slot">
                  {[1, 2, 3, 4].map(n => (
                    <div key={n} className="bg-[#FDFAD8] border-4 border-[#47510B] p-4 rounded-2xl flex items-center gap-4 shadow-[4px_4px_0_0_#47510B]">
                      <Truck className="text-[#AB1717]" size={32} />
                      <div>
                        <p className="font-black text-[#47510B]">TRK_NODE_{n}</p>
                        <p className="text-[10px] font-bold text-[#AB1717]">STATUS: DEPLOYED</p>
                      </div>
                    </div>
                  ))}
                </div>
              )}
              {activeTab === 'HISTORY' && (
                <div className="w-full bg-[#47510B] p-6 rounded-2xl border-4 border-[#FDFAD8]/30 font-mono text-sm text-[#CAD23C] animate-slot">
                   <p className="text-[#FDFAD8] mb-2 font-black tracking-widest uppercase underline">Terminal_Output</p>
                   <p>{">"} INITIALIZING_CORE_DUMP...</p>
                   <p>{">"} TRASH_VOL_NODE_09: 88% CAPACITY</p>
                   <p>{">"} ROUTE_OPTIMIZATION_SUCCESSFUL</p>
                </div>
              )}
              {activeTab === 'USERS' && (
                <div className="flex flex-col items-center gap-4 animate-slot">
                   <Target size={100} className="text-[#AB1717]" />
                   <h2 className="text-3xl font-black text-[#47510B] uppercase italic">Personnel_Access</h2>
                </div>
              )}
            </div>
          </div>
        </div>

        {/* --- THE SELECTOR CONSOLE (Bottom Tabs) --- */}
        <div className="grid grid-cols-4 gap-4 px-4">
          {navItems.map((item) => (
            <button
              key={item.id}
              onClick={() => setActiveTab(item.id)}
              className={`
                relative h-24 rounded-2xl border-[6px] border-[#47510B] transition-all flex flex-col items-center justify-center gap-2
                ${activeTab === item.id 
                  ? 'bg-[#CAD23C] translate-y-2 shadow-none' 
                  : 'bg-[#FDFAD8] -translate-y-2 shadow-[0_8px_0_0_#47510B] hover:-translate-y-3'}
              `}
            >
              <div className={`${activeTab === item.id ? 'text-[#47510B]' : 'text-[#AB1717]'}`}>
                {item.icon}
              </div>
              <span className={`text-[9px] font-black uppercase tracking-tighter ${activeTab === item.id ? 'text-[#47510B]' : 'text-[#AB1717]'}`}>
                {item.label}
              </span>

              {/* Little indicator light on the button */}
              <div className={`absolute top-2 right-2 w-2 h-2 rounded-full border border-[#47510B] ${activeTab === item.id ? 'bg-[#AB1717] animate-pulse' : 'bg-[#47510B]'}`} />
            </button>
          ))}
        </div>

        {/* DECORATIVE BOLTS */}
        <div className="absolute top-4 left-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
        <div className="absolute top-4 right-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
        <div className="absolute bottom-4 left-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
        <div className="absolute bottom-4 right-4 w-4 h-4 bg-[#47510B] rounded-full shadow-inner" />
      </div>

      {/* SYSTEM TAG */}
      <div className="mt-8 flex gap-8 items-center opacity-40 grayscale">
        <Zap size={20} className="text-[#AB1717]" />
        <p className="text-[10px] font-black uppercase tracking-[0.8em] text-[#47510B]">Industrial_Control_System_V3</p>
        <Database size={20} className="text-[#AB1717]" />
      </div>
    </div>
  );
};

export default Dashboard;
